-- =====================================================================
--  KosKu - Database MySQL / MariaDB
--  Sesuai Bab 4.5 laporan: users, rooms, rentals, invoices, payments + files (penyimpanan gambar)
--
--  Cara import:
--    * phpMyAdmin : tab Import -> pilih file ini -> Go
--    * Terminal   : mysql -u root -p < database.sql
--
--  File ini membuat database "kosku" (jika belum ada), lalu membuat ulang
--  semua tabel, semua tabel, dan data demo. Tanggal data demo dihitung relatif
--  terhadap hari saat file di-import, jadi selalu terlihat "baru".
--
--  Akun demo:
--    Owner    : owner@kosku.com / owner123
--    Penghuni : budi@, sari@, dewi@, rudi@kosku.com / tenant123
-- =====================================================================

CREATE DATABASE IF NOT EXISTS kosku CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kosku;

-- Hapus tabel lama (jika ada) supaya file ini aman di-import berulang kali
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS payments;
DROP TABLE IF EXISTS invoices;
DROP TABLE IF EXISTS rentals;
DROP TABLE IF EXISTS rooms;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS files;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
--  STRUKTUR TABEL
-- ---------------------------------------------------------------------

CREATE TABLE users (
  id         INT          NOT NULL AUTO_INCREMENT,
  name       VARCHAR(100) NOT NULL,
  email      VARCHAR(100) NOT NULL,
  password   VARCHAR(255) NOT NULL COMMENT 'hash bcrypt',
  phone      VARCHAR(20)  NULL,
  role       ENUM('OWNER','TENANT') NOT NULL DEFAULT 'TENANT',
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB;

CREATE TABLE rooms (
  id          INT          NOT NULL AUTO_INCREMENT,
  room_number VARCHAR(10)  NOT NULL COMMENT 'contoh: A01',
  type        VARCHAR(50)  NOT NULL COMMENT 'contoh: Standar / AC',
  price       INT          NOT NULL COMMENT 'harga sewa per bulan',
  size        VARCHAR(20)  NULL COMMENT 'contoh: 3 x 4 m',
  facilities  TEXT         NOT NULL COMMENT 'satu fasilitas per baris',
  description TEXT         NOT NULL,
  status      ENUM('AVAILABLE','OCCUPIED') NOT NULL DEFAULT 'AVAILABLE'
              COMMENT 'diatur otomatis oleh sistem, bukan dari form',
  is_active   TINYINT(1)   NOT NULL DEFAULT 1
              COMMENT 'kamar nonaktif tidak tampil dan tidak bisa diajukan',
  image_url   VARCHAR(255) NULL,
  gallery_urls TEXT        NULL COMMENT 'JSON: url foto 2, 3, 4',
  PRIMARY KEY (id),
  UNIQUE KEY uq_rooms_room_number (room_number)
) ENGINE=InnoDB;

CREATE TABLE rentals (
  id              INT         NOT NULL AUTO_INCREMENT,
  user_id         INT         NOT NULL,
  room_id         INT         NOT NULL,
  start_date      DATETIME(3) NOT NULL,
  duration_months INT         NOT NULL,
  end_date        DATETIME(3) NOT NULL COMMENT 'start_date + duration_months',
  status          ENUM('PENDING','ACTIVE','REJECTED','ENDED') NOT NULL DEFAULT 'PENDING',
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_rentals_user (user_id),
  KEY idx_rentals_room (room_id),
  CONSTRAINT fk_rentals_user FOREIGN KEY (user_id) REFERENCES users (id),
  CONSTRAINT fk_rentals_room FOREIGN KEY (room_id) REFERENCES rooms (id)
) ENGINE=InnoDB;

CREATE TABLE invoices (
  id        INT         NOT NULL AUTO_INCREMENT,
  rental_id INT         NOT NULL,
  period    VARCHAR(7)  NOT NULL COMMENT 'contoh: 2026-11',
  amount    INT         NOT NULL,
  due_date  DATETIME(3) NOT NULL,
  status    ENUM('UNPAID','WAITING_VERIFICATION','PAID') NOT NULL DEFAULT 'UNPAID',
  PRIMARY KEY (id),
  UNIQUE KEY uq_invoices_rental_period (rental_id, period),
  CONSTRAINT fk_invoices_rental FOREIGN KEY (rental_id) REFERENCES rentals (id)
) ENGINE=InnoDB;

CREATE TABLE payments (
  id         INT          NOT NULL AUTO_INCREMENT,
  invoice_id INT          NOT NULL,
  proof_url  VARCHAR(255) NOT NULL COMMENT 'lokasi file bukti transfer',
  paid_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'waktu unggah',
  status     ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',
  note       VARCHAR(255) NULL COMMENT 'alasan penolakan',
  PRIMARY KEY (id),
  KEY idx_payments_invoice (invoice_id),
  CONSTRAINT fk_payments_invoice FOREIGN KEY (invoice_id) REFERENCES invoices (id)
) ENGINE=InnoDB;

CREATE TABLE files (
  id         INT          NOT NULL AUTO_INCREMENT,
  name       VARCHAR(191) NOT NULL COMMENT 'nama unik, dipakai di URL /api/files/{name}',
  mime       VARCHAR(50)  NOT NULL,
  data       LONGBLOB     NOT NULL COMMENT 'isi gambar (foto kamar / bukti transfer)',
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_files_name (name)
) ENGINE=InnoDB;

